// fl-engine: FreeLang Mobile 실행 엔진 FFI
// Rust로 작성된 freelang-vm을 C 바인딩으로 노출합니다.
// Android: JNI 브릿지가 이 함수들을 호출
// iOS: Swift 브릿지가 이 함수들을 호출

use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int};
use std::ptr;
use std::sync::Mutex;

// ============================================================================
// 데이터 구조
// ============================================================================

/// 실행 결과 구조체
#[repr(C)]
pub struct FlResult {
    pub success: c_int,           // 1 = 성공, 0 = 실패
    pub output: *mut c_char,      // 표준 출력 (C가 free 해야 함)
    pub error: *mut c_char,       // 오류 메시지
    pub time_ms: u32,             // 실행 시간
    pub exit_code: c_int,         // 종료 코드
}

/// 토큰 구조체 (구문 강조용)
#[repr(C)]
pub struct FlToken {
    pub token_type: c_int,        // 0=keyword, 1=identifier, 2=number 등
    pub start: c_int,             // 시작 위치
    pub length: c_int,            // 길이
}

/// 오류 구조체 (LSP용)
#[repr(C)]
pub struct FlError {
    pub line: c_int,
    pub col: c_int,
    pub message: *mut c_char,
    pub severity: c_int,          // 0=error, 1=warning, 2=info
}

/// LSP 자동완성 아이템
#[repr(C)]
pub struct FlCompletion {
    pub label: *mut c_char,
    pub kind: c_int,              // 1=keyword, 2=function, 3=variable 등
    pub detail: *mut c_char,
}

// ============================================================================
// 엔진 인스턴스 (전역 상태 관리)
// ============================================================================

lazy_static::lazy_static! {
    static ref ENGINE_STATE: Mutex<Option<String>> = Mutex::new(None);
}

// ============================================================================
// Public API (C에서 호출 가능)
// ============================================================================

/// 엔진 초기화
/// 반환: 항상 0 (성공)
#[no_mangle]
pub extern "C" fn fl_engine_init() -> c_int {
    let mut state = ENGINE_STATE.lock().unwrap();
    *state = Some(String::from("initialized"));
    0
}

/// 엔진 정리
#[no_mangle]
pub extern "C" fn fl_engine_shutdown() {
    let mut state = ENGINE_STATE.lock().unwrap();
    *state = None;
}

/// 경로 A: 바이트코드 인터프리터로 실행 (iOS 안전)
///
/// # 인자
/// - `source`: FreeLang 소스 코드 (null-terminated C string)
/// - `timeout_ms`: 타임아웃 (밀리초, 0=무제한)
