// engine_bridge.dart - fl-engine과의 Platform Channel 통신
// Android: JNI를 통해 fl-engine Rust 함수 호출
// iOS: Swift 브릿지를 통해 호출

import 'package:flutter/services.dart';

enum RunMode {
  bytecode, // 경로 A: VM 바이트코드 인터프리터 (iOS 안전)
  native,   // 경로 B: C 생성 후 네이티브 컴파일 (Android만)
}

class ExecutionResult {
  final bool success;
  final String output;
  final String error;
  final int timeMs;
  final int exitCode;

  ExecutionResult({
    required this.success,
    required this.output,
    required this.error,
    required this.timeMs,
    required this.exitCode,
  });

  factory ExecutionResult.fromMap(Map<dynamic, dynamic> map) {
    return ExecutionResult(
      success: map['success'] as bool? ?? false,
      output: map['output'] as String? ?? '',
      error: map['error'] as String? ?? '',
      timeMs: map['time_ms'] as int? ?? 0,
      exitCode: map['exit_code'] as int? ?? 1,
    );
  }
}

class FlEngineBridge {
  static const MethodChannel _channel =
      MethodChannel('dev.freelang/engine');

  /// FreeLang 코드 실행
  ///
  /// [code] - FreeLang 소스 코드
  /// [timeoutMs] - 실행 타임아웃 (밀리초, 기본 5000)
  /// [mode] - 실행 경로 (기본 바이트코드)
  static Future<ExecutionResult> run(
    String code, {
    int timeoutMs = 5000,
    RunMode mode = RunMode.bytecode,
  }) async {
    try {
      final result = await _channel.invokeMethod('run', {
        'code': code,
        'timeout': timeoutMs,
        'mode': mode.index,
      });

      return ExecutionResult.fromMap(result);
    } on PlatformException catch (e) {
      return ExecutionResult(
        success: false,
        output: '',
        error: '플랫폼 오류: ${e.message}',
        timeMs: 0,
        exitCode: -1,
      );
    }
  }

  /// 코드 토큰화 (구문 강조)
  static Future<List<Token>> tokenize(String code) async {
    try {
      final result = await _channel.invokeMethod('tokenize', {
        'code': code,
      });

      final tokens = result as List;
      return tokens
          .cast<Map<dynamic, dynamic>>()
          .map((t) => Token.fromMap(t))
          .toList();
    } catch (e) {
      return [];
    }
  }

  /// 코드 검사 (오류 수집)
  static Future<List<LspError>> check(String code) async {
    try {
      final result = await _channel.invokeMethod('check', {
        'code': code,
      });

      final errors = result as List;
      return errors
          .cast<Map<dynamic, dynamic>>()
          .map((e) => LspError.fromMap(e))
          .toList();
    } catch (e) {
      return [];
    }
  }

  /// 자동완성 (LSP)
  static Future<List<Completion>> complete(
    String code,
    int line,
    int col,
  ) async {
    try {
      final result = await _channel.invokeMethod('complete', {
        'code': code,
        'line': line,
        'col': col,
      });

      final completions = result as List;
      return completions
          .cast<Map<dynamic, dynamic>>()
          .map((c) => Completion.fromMap(c))
          .toList();
    } catch (e) {
      return [];
    }
  }
}

/// 토큰 (구문 강조용)
class Token {
  final int type; // 0=keyword, 1=identifier, 2=number, ...
  final int start;
  final int length;

  Token({
    required this.type,
    required this.start,
    required this.length,
  });

  factory Token.fromMap(Map<dynamic, dynamic> map) {
    return Token(
      type: map['type'] as int? ?? 0,
      start: map['start'] as int? ?? 0,
      length: map['length'] as int? ?? 0,
    );
  }
}

/// LSP 오류
class LspError {
  final int line;
  final int col;
  final String message;
  final int severity; // 0=error, 1=warning, 2=info

  LspError({
    required this.line,
    required this.col,
    required this.message,
    required this.severity,
  });

  factory LspError.fromMap(Map<dynamic, dynamic> map) {
    return LspError(
      line: map['line'] as int? ?? 0,
      col: map['col'] as int? ?? 0,
      message: map['message'] as String? ?? '',
      severity: map['severity'] as int? ?? 0,
    );
  }

  bool get isError => severity == 0;
  bool get isWarning => severity == 1;
}

/// 자동완성 아이템
class Completion {
  final String label;
  final int kind; // 1=keyword, 2=function, 3=variable
  final String detail;

  Completion({
    required this.label,
    required this.kind,
    required this.detail,
  });

  factory Completion.fromMap(Map<dynamic, dynamic> map) {
    return Completion(
      label: map['label'] as String? ?? '',
      kind: map['kind'] as int? ?? 0,
      detail: map['detail'] as String? ?? '',
    );
  }
}

