// file_manager.dart - 로컬 .fl 파일 관리

import 'dart:io';
import 'package:path_provider/path_provider.dart';

class FileInfo {
  final String name;
  final String path;
  final DateTime modified;
  final int size;

  FileInfo({
    required this.name,
    required this.path,
    required this.modified,
    required this.size,
  });
}

class FileManager {
  late Directory _codeDirectory;
  static const String _codeFolder = 'freelang_code';

  Future<void> initialize() async {
    final documents = await getApplicationDocumentsDirectory();
    _codeDirectory = Directory('${documents.path}/$_codeFolder');
    if (!_codeDirectory.existsSync()) {
      _codeDirectory.createSync(recursive: true);
    }
  }

  /// 파일 목록 가져오기
  Future<List<FileInfo>> listFiles() async {
    final files = _codeDirectory.listSync();
    return files
        .whereType<File>()
        .where((f) => f.path.endsWith('.fl'))
        .map((f) {
          final stat = f.statSync();
          return FileInfo(
            name: f.path.split('/').last,
            path: f.path,
            modified: stat.modified,
            size: stat.size,
          );
        })
        .toList()
        ..sort((a, b) => b.modified.compareTo(a.modified));
  }

  /// 파일 읽기
  Future<String> readFile(String path) async {
    return File(path).readAsString();
  }

  /// 파일 저장
  Future<void> saveFile(String name, String content) async {
    if (!name.endsWith('.fl')) {
      name += '.fl';
    }
    final file = File('${_codeDirectory.path}/$name');
    await file.writeAsString(content);
  }

  /// 파일 삭제
  Future<void> deleteFile(String path) async {
    await File(path).delete();
  }

  /// 파일 이름 변경
  Future<void> renameFile(String oldPath, String newName) async {
    await File(oldPath).rename('${_codeDirectory.path}/$newName');
  }

  /// 디렉토리 경로
  String get codePath => _codeDirectory.path;
}

