// leaderboard_screen.dart - 리더보드 (기여자 랭킹)

import 'package:flutter/material.dart';

class LeaderboardEntry {
  final int rank;
  final String username;
  final int score;
  final int contributions;

  LeaderboardEntry({
    required this.rank,
    required this.username,
    required this.score,
    required this.contributions,
  });
}

class LeaderboardScreen extends StatefulWidget {
  const LeaderboardScreen({Key? key}) : super(key: key);

  @override
  State<LeaderboardScreen> createState() => _LeaderboardScreenState();
}

class _LeaderboardScreenState extends State<LeaderboardScreen> {
  final entries = [
    LeaderboardEntry(
      rank: 1,
      username: 'alice_dev',
      score: 2850,
      contributions: 45,
    ),
    LeaderboardEntry(
      rank: 2,
      username: 'bob_coder',
      score: 2320,
      contributions: 38,
    ),
    LeaderboardEntry(
      rank: 3,
      username: 'charlie_fl',
      score: 1950,
      contributions: 32,
    ),
    LeaderboardEntry(
      rank: 4,
      username: 'diana_lang',
      score: 1650,
      contributions: 27,
    ),
    LeaderboardEntry(
      rank: 5,
      username: 'eve_mobile',
      score: 1420,
      contributions: 23,
    ),
  ];

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 기간 선택
        Padding(
          padding: const EdgeInsets.all(12),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceEvenly,
            children: ['주간', '월간', '전체']
                .map((period) => ChoiceChip(
                      label: Text(period),
                      selected: period == '주간',
                      onSelected: (selected) {
                        // 기간 변경
                      },
                    ))
                .toList(),
          ),
        ),

        // 리더보드 목록
        Expanded(
          child: ListView.builder(
            itemCount: entries.length,
            itemBuilder: (context, index) {
              final entry = entries[index];
              final isTopThree = entry.rank <= 3;

              return Container(
                margin: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                decoration: BoxDecoration(
                  border: Border(
                    left: BorderSide(
                      color: isTopThree
                          ? [Colors.amber, Colors.grey, Colors.orange][
                              entry.rank - 1]
                          : Colors.transparent,
                      width: isTopThree ? 3 : 0,
                    ),
                  ),
                ),
                child: Card(
                  child: ListTile(
                    leading: _buildRankBadge(entry.rank),
                    title: Text(
                      entry.username,
                      style: const TextStyle(fontWeight: FontWeight.bold),
                    ),
                    subtitle: Text(
                      '${entry.contributions} 기여 • ${entry.score} 포인트',
                    ),
                    trailing: _buildRankChange(entry.rank),
                  ),
                ),
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildRankBadge(int rank) {
    final colors = [Colors.amber, Colors.grey, Colors.orange];
    final color = rank <= 3 ? colors[rank - 1] : Colors.blue;

    return Container(
      width: 40,
      height: 40,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: color,
      ),
      child: Center(
        child: Text(
          '$rank',
          style: const TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.bold,
          ),
        ),
      ),
    );
  }

  Widget _buildRankChange(int rank) {
    // 임시: 모두 up (실제로는 이전 순위와 비교)
    return Column(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        const Icon(Icons.arrow_upward, color: Colors.green, size: 16),
        Text(
          '${2 - rank}',
          style: const TextStyle(
            fontSize: 10,
            color: Colors.green,
            fontWeight: FontWeight.bold,
          ),
        ),
      ],
    );
  }
}

