  /// **예외**: PlatformException (플랫폼 오류만)
  static Future<ExecutionResult> run(
    String code, {
    int timeoutMs = 5000,
    RunMode mode = RunMode.bytecode,
  }) async {
    // 입력 검증
    if (code.isEmpty) {
      return ExecutionResult(
        success: false,
        output: '',
        error: '코드가 비어있습니다',
        timeMs: 0,
        exitCode: -1,
      );
    }

    if (timeoutMs < 100 || timeoutMs > 300000) {
      return ExecutionResult(
        success: false,
        output: '',
        error: '타임아웃은 100~300000ms 범위여야 합니다',
        timeMs: 0,
        exitCode: -1,
      );
    }

    // 초기화 확인
    if (!_initialized) {
      final init = await initialize();
      if (!init) {
        return ExecutionResult(
          success: false,
          output: '',
          error: '엔진 초기화 실패',
          timeMs: 0,
          exitCode: -1,
        );
      }
    }

    try {
      final startTime = DateTime.now();

      final result = await _channel.invokeMethod<Map<dynamic, dynamic>>(
        'run',
        {
          'code': code,
          'timeout': timeoutMs,
          'mode': mode.index,
        },
      ).timeout(
        Duration(milliseconds: timeoutMs + 1000),
        onTimeout: () => {
          'success': false,
          'output': '',
          'error': '타임아웃 (${timeoutMs}ms)',
          'time_ms': timeoutMs,
          'exit_code': -1,
