enum RunMode {
  bytecode, // 경로 A: VM 바이트코드 인터프리터 (iOS 안전)
  native,   // 경로 B: C 생성 후 네이티브 컴파일 (Android만)
}

class ExecutionResult {
  final bool success;
  final String output;
  final String error;
  final int timeMs;
  final int exitCode;

  ExecutionResult({
    required this.success,
    required this.output,
    required this.error,
    required this.timeMs,
    required this.exitCode,
  });

  factory ExecutionResult.fromMap(Map<dynamic, dynamic> map) {
    return ExecutionResult(
      success: (map['success'] as bool?) ?? false,
      output: (map['output'] as String?) ?? '',
      error: (map['error'] as String?) ?? '',
      timeMs: (map['time_ms'] as int?) ?? 0,
      exitCode: (map['exit_code'] as int?) ?? 1,
    );
  }

  @override
  String toString() =>
      'ExecutionResult(success: $success, time: ${timeMs}ms, code: $exitCode)';
}

class FlEngineBridge {
  static const MethodChannel _channel =
      MethodChannel('dev.freelang/engine');

  static bool _initialized = false;

  /// 엔진 초기화 (앱 시작 시 한 번만)
  static Future<bool> initialize() async {
    if (_initialized) return true;

    try {
      final result = await _channel.invokeMethod<int>('init');
      _initialized = result == 0;
      return _initialized;
    } on PlatformException catch (e) {
      print('[FlEngine] Init failed: ${e.message}');
      return false;
    }
  }

  /// FreeLang 코드 실행
  ///
  /// [code] - FreeLang 소스 코드
  /// [timeoutMs] - 실행 타임아웃 (밀리초, 기본 5000)
  /// [mode] - 실행 경로 (기본 바이트코드)
  ///
  /// **반환**: ExecutionResult (항상 성공)
  /// **예외**: PlatformException (플랫폼 오류만)
  static Future<ExecutionResult> run(
    String code, {
    int timeoutMs = 5000,
    RunMode mode = RunMode.bytecode,
  }) async {
    // 입력 검증
    if (code.isEmpty) {
      return ExecutionResult(
        success: false,
        output: '',
        error: '코드가 비어있습니다',
        timeMs: 0,
        exitCode: -1,
      );
    }

    if (timeoutMs < 100 || timeoutMs > 300000) {
      return ExecutionResult(
        success: false,
        output: '',
        error: '타임아웃은 100~300000ms 범위여야 합니다',
        timeMs: 0,
        exitCode: -1,
      );
    }

    // 초기화 확인
    if (!_initialized) {
      final init = await initialize();
      if (!init) {
        return ExecutionResult(
          success: false,
          output: '',
          error: '엔진 초기화 실패',
          timeMs: 0,
          exitCode: -1,
        );
      }
    }

    try {
      final startTime = DateTime.now();

      final result = await _channel.invokeMethod<Map<dynamic, dynamic>>(
        'run',
        {
          'code': code,
          'timeout': timeoutMs,
          'mode': mode.index,
        },
      ).timeout(
        Duration(milliseconds: timeoutMs + 1000),
        onTimeout: () => {
          'success': false,
          'output': '',
          'error': '타임아웃 (${timeoutMs}ms)',
          'time_ms': timeoutMs,
          'exit_code': -1,
        },
      );

      if (result == null) {
        return ExecutionResult(
          success: false,
          output: '',
          error: '플랫폼에서 결과를 반환하지 않음',
          timeMs: DateTime.now().difference(startTime).inMilliseconds,
          exitCode: -1,
        );
      }

      return ExecutionResult.fromMap(result);
    } on PlatformException catch (e) {
      return ExecutionResult(
        success: false,
        output: '',
        error: '[플랫폼 오류] ${e.message ?? e.code}',
        timeMs: 0,
        exitCode: -2,
      );
    } catch (e) {
      return ExecutionResult(
        success: false,
        output: '',
        error: '[오류] $e',
        timeMs: 0,
        exitCode: -3,
      );
    }
  }

  /// 코드 토큰화 (구문 강조용)
  static Future<List<Token>> tokenize(String code) async {
    if (code.isEmpty) return [];

    try {
      final result = await _channel.invokeMethod<List>(
        'tokenize',
        {'code': code},
      );

      if (result == null) return [];

      return result
          .cast<Map<dynamic, dynamic>>()
          .map((t) => Token.fromMap(t))
          .toList();
    } catch (e) {
      print('[FlEngine] Tokenize error: $e');
      return [];
    }
  }

  /// 코드 검사 (오류 수집)
  static Future<List<LspError>> check(String code) async {
    if (code.isEmpty) return [];

    try {
      final result = await _channel.invokeMethod<List>(
        'check',
        {'code': code},
      );

      if (result == null) return [];

      return result
          .cast<Map<dynamic, dynamic>>()
          .map((e) => LspError.fromMap(e))
          .toList();
    } catch (e) {
      print('[FlEngine] Check error: $e');
      return [];
    }
  }

  /// 자동완성 (LSP)
  static Future<List<Completion>> complete(
    String code,
    int line,
    int col,
  ) async {
    try {
      final result = await _channel.invokeMethod<List>(
        'complete',
        {
          'code': code,
          'line': line,
          'col': col,
        },
      );

      if (result == null) return [];

      return result
          .cast<Map<dynamic, dynamic>>()
          .map((c) => Completion.fromMap(c))
          .toList();
    } catch (e) {
      print('[FlEngine] Complete error: $e');
      return [];
    }
  }

  /// 엔진 정리 (앱 종료 시)
  static Future<void> shutdown() async {
    try {
      await _channel.invokeMethod('shutdown');
      _initialized = false;
    } catch (e) {
      print('[FlEngine] Shutdown error: $e');
    }
  }
}

/// 토큰 (구문 강조용)
class Token {
  final int type; // 0=keyword, 1=identifier, 2=number, 3=string, 4=comment
  final int start;
  final int length;

  Token({
    required this.type,
    required this.start,
    required this.length,
  });

  factory Token.fromMap(Map<dynamic, dynamic> map) {
    return Token(
      type: map['type'] as int? ?? 0,
      start: map['start'] as int? ?? 0,
      length: map['length'] as int? ?? 0,
    );
  }

  String get typeName {
    const names = ['keyword', 'identifier', 'number', 'string', 'comment'];
    return names.length > type ? names[type] : 'unknown';
  }

  @override
  String toString() => 'Token($typeName, $start, $length)';
}

/// LSP 오류
class LspError {
  final int line;
  final int col;
  final String message;
  final int severity; // 0=error, 1=warning, 2=info

  LspError({
    required this.line,
    required this.col,
    required this.message,
    required this.severity,
  });

  factory LspError.fromMap(Map<dynamic, dynamic> map) {
    return LspError(
      line: map['line'] as int? ?? 0,
      col: map['col'] as int? ?? 0,
      message: map['message'] as String? ?? '',
      severity: map['severity'] as int? ?? 0,
    );
  }

  bool get isError => severity == 0;
  bool get isWarning => severity == 1;
  bool get isInfo => severity == 2;

  @override
  String toString() => 'Error($line:$col) $message';
}

/// 자동완성 아이템
class Completion {
  final String label;
  final int kind; // 1=keyword, 2=function, 3=variable, 4=type
  final String detail;

  Completion({
    required this.label,
    required this.kind,
    required this.detail,
  });

  factory Completion.fromMap(Map<dynamic, dynamic> map) {
    return Completion(
      label: map['label'] as String? ?? '',
      kind: map['kind'] as int? ?? 0,
      detail: map['detail'] as String? ?? '',
    );
  }

  String get kindName {
    const names = ['', 'keyword', 'function', 'variable', 'type'];
    return names.length > kind ? names[kind] : 'unknown';
  }

  @override
  String toString() => 'Completion($label, $kindName)';
}

